CREATE TABLE IF NOT EXISTS affiliate_profiles (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,code VARCHAR(80) NOT NULL,commission_rate DECIMAL(5,2) NOT NULL DEFAULT 18.00,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),UNIQUE KEY uq_affiliate_user(user_id),UNIQUE KEY uq_affiliate_code(code),CONSTRAINT fk_affiliate_profile_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS affiliate_products (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,name VARCHAR(180) NOT NULL,category VARCHAR(120) NOT NULL,price DECIMAL(12,2) NOT NULL DEFAULT 0,status ENUM('Ativo','Em revisão','Inativo') NOT NULL DEFAULT 'Ativo',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY ix_affiliate_products_user(user_id),CONSTRAINT fk_affiliate_products_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS affiliate_orders (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,external_id VARCHAR(100) NULL,customer_name VARCHAR(160) NULL,product_name VARCHAR(180) NULL,value DECIMAL(12,2) NOT NULL DEFAULT 0,status ENUM('Pago','Pendente','Cancelado') NOT NULL DEFAULT 'Pendente',ordered_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY ix_affiliate_orders_user_date(user_id,ordered_at),CONSTRAINT fk_affiliate_orders_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS affiliate_clicks (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,user_id BIGINT UNSIGNED NOT NULL,code VARCHAR(80) NULL,created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(id),KEY ix_affiliate_clicks_user_date(user_id,created_at),CONSTRAINT fk_affiliate_clicks_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
